class Solution {
public:
    string digitSum(string s, int k) {
        while ((int)s.size() > k) {
            string t;
            int n = (int)s.size();
            for (int i = 0; i < n; i += k) {
                int sum = 0;
                for (int j = i; j < n && j < i + k; j++) {
                    sum += s[j] - '0';
                }
                t += to_string(sum);
            }
            s = t;
        }
        return s;
    }
};
